    {
      "claim": "Nach § 573c BGB beträgt die Kündigungsfrist für eine Wohnung länger als 5 Jahre Mietzeit mindestens 6 Monate zum Monatsende",
      "verdict": "contradicted"
    },
    {
      "claim": "Bei Staffelmietverträgen gelten die im Vertrag festgelegten Staffelraten und eine vorzeitige Kündigung ist meist nicht möglich",
      "verdict": "unverifiable"
    },
    {
      "claim": "Bei befristeten Mietverträgen ist eine ordentliche Kündigung grundsätzlich nicht möglich, es sei denn, es wurde im Vertrag eine Kündigungsmöglichkeit vereinbart",
      "verdict": "unverifiable"
    },
    {
      "claim": "Die Kündigung muss schriftlich erfolgen",
      "verdict": "unverifiable"
    },
    {
      "claim": "Eine mündliche Kündigung ist nicht wirksam",
      "verdict": "unverifiable"
    },
    {
      "claim": "Eine E-Mail ohne Unterschrift gilt in der Regel nicht als schriftliche Kündigung",
      "verdict": "unverifiable"
    },
    {
      "claim": "Die Kündigung muss unterschrieben sein",
      "verdict": "unverifiable"
    },
    {
      "claim": "Die Kündigung muss dem/den Empfänger(n) zugestellt werden, am besten per Einschreiben mit Rückschein oder durch persönliche Übergabe gegen Quittung",
      "verdict": "unverifiable"
    },
    {
      "claim": "Die Kündigung muss klar und eindeutig formuliert sein (z. B. „Hiermit kündige ich das Mietverhältnis zum …“)",
      "verdict": "unverifiable"
    }
